// Banco de frases do dia do Xadrez Express. Uma por dia, sem repetir por mais de um ano.
window.XE_FRASES = [
  { t: 'Não acredito em psicologia. Acredito em bons lances.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'São os pequenos detalhes que são vitais. Coisas pequenas fazem coisas grandes acontecerem.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Técnica não é fazer mil embaixadinhas. Isso qualquer um aprende treinando, e depois pode trabalhar no circo. Técnica é passar a bola de primeira, na velocidade certa, no pé certo do companheiro.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'O vencedor da partida é o jogador que comete o penúltimo erro.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Os obstáculos não precisam parar você. Se der de cara com um muro, não dê meia-volta nem desista. Descubra como escalá-lo, atravessá-lo ou contorná-lo.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'Eu atacava porque era a única coisa que sabia fazer. Hoje ataco porque sei que é o que funciona melhor.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Os melhores do mundo não são os melhores porque ganham todos os pontos. É porque sabem que vão perder de novo e de novo, e aprenderam a lidar com isso.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Se você fica esperando a sorte aparecer, a vida se torna muito chata.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Ninguém mais vai lá. É cheio demais.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'O futuro pertence a quem tem os bispos.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Compromisso individual com um esforço coletivo: é isso que faz funcionar um time, uma empresa, uma sociedade, uma civilização.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'Passo horas jogando xadrez porque acho muito divertido. O dia em que deixar de ser divertido será o dia em que eu paro.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Quem não tem coragem suficiente para correr riscos não conquistará nada na vida.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'Durante uma competição, o mestre de xadrez deve ser uma combinação de fera e monge.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Eu tenho dúvidas. Tenho inseguranças. Tenho medo de fracassar. Todos nós temos. Você não nega isso, mas também não se rende. Você abraça.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'A maioria dos jogadores não gosta de perder e considera a derrota algo vergonhoso. É uma atitude errada. Quem quer se aperfeiçoar deve encarar suas derrotas como lições.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'A derrota é um estado de espírito; ninguém está derrotado até aceitar a derrota como realidade.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'Um sacrifício se refuta melhor aceitando-o.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Se você não perde, não consegue desfrutar das vitórias. Então preciso aceitar as duas coisas.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'Acho que as metas nunca devem ser fáceis; elas devem obrigar você a trabalhar, mesmo que sejam desconfortáveis no momento.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Para cada porta que os computadores fecharam, eles abriram uma nova.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'O sucesso não acontece por acaso. É trabalho duro, perseverança, aprendizado, estudo, sacrifício e, acima de tudo, amor pelo que você está fazendo ou aprendendo a fazer.', a: 'Pelé', p: 'Rei do futebol' },
  { t: 'No Gambito do Rei não é preciso muito para o desastre acontecer: um lance descuidado e as pretas podem estar à beira do abismo.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'Grande é a vitória, mas a amizade de todos é ainda maior.', a: 'Emil Zátopek', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'A educação no xadrez tem de ser uma educação no pensamento e no julgamento independentes. O xadrez não deve ser decorado.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'O verdadeiro heroísmo é notavelmente sóbrio, nada dramático. Não é o impulso de superar os outros a qualquer custo, mas o impulso de servir aos outros a qualquer custo.', a: 'Arthur Ashe', p: 'Campeão de Wimbledon' },
  { t: 'Muitas vezes jogo um lance que eu sei como refutar.', a: 'Bent Larsen', p: 'Grande mestre dinamarquês' },
  { t: 'Campeões continuam jogando até acertar.', a: 'Billie Jean King', p: 'Lenda do tênis' },
  { t: 'Estou absolutamente convencido de que no xadrez, embora ele continue sendo um jogo, não há nada de acidental.', a: 'Tigran Petrosian', p: 'Campeão mundial de xadrez' },
  { t: 'Só os disciplinados são livres na vida. Se você é indisciplinado, é escravo dos seus humores e das suas paixões.', a: 'Eliud Kipchoge', p: 'Bicampeão olímpico da maratona' },
  { t: 'Xadrez é imaginação.', a: 'David Bronstein', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Se você deixa de ir atrás de um espaço que existe, já não é mais um piloto de corrida.', a: 'Ayrton Senna', p: 'Tricampeão de Fórmula 1' },
  { t: 'Todo mês eu examino umas dez mil partidas, para não deixar escapar nenhuma ideia ou tendência nova.', a: 'Vladimir Kramnik', p: 'Campeão mundial de xadrez' },
  { t: 'As amizades nascidas no campo da disputa esportiva são o verdadeiro ouro da competição. Os prêmios enferrujam; os amigos não juntam poeira.', a: 'Jesse Owens', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Quem pensa que é fácil jogar xadrez está enganado. Durante a partida o jogador vive à flor da pele e, ao mesmo tempo, precisa manter a compostura perfeita.', a: 'Viktor Korchnoi', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'O sucesso de cada mulher deveria ser uma inspiração para outra. Somos mais fortes quando torcemos umas pelas outras.', a: 'Serena Williams', p: 'Lenda do tênis' },
  { t: 'O xadrez é a arte que expressa a ciência da lógica.', a: 'Mikhail Botvinnik', p: 'Campeão mundial de xadrez' },
  { t: 'Precisamos proteger a nossa mente e o nosso corpo, em vez de simplesmente ir lá e fazer o que o mundo quer que façamos.', a: 'Simone Biles', p: 'Campeã olímpica de ginástica' },
  { t: 'Comemore o que você conquistou, mas suba um pouco mais o sarrafo a cada vez que tiver sucesso.', a: 'Mia Hamm', p: 'Bicampeã mundial de futebol' },
  { t: 'A beleza de uma partida de xadrez costuma ser avaliada, e com razão, pelos sacrifícios que ela contém.', a: 'Rudolf Spielmann', p: 'Mestre austríaco de xadrez' },
  { t: 'É difícil vencer uma pessoa que nunca desiste.', a: 'Babe Ruth', p: 'Lenda do beisebol' },
  { t: 'Primeiro restringir, depois bloquear e, por fim, destruir.', a: 'Aron Nimzowitsch', p: 'Mestre e teórico do xadrez' },
  { t: 'Os médicos me disseram que eu nunca mais andaria. Minha mãe me disse que eu andaria. Acreditei na minha mãe.', a: 'Wilma Rudolph', p: 'Tricampeã olímpica de atletismo' },
  { t: 'Na ideia do xadrez e no desenvolvimento da mente enxadrística temos um retrato da luta intelectual da humanidade.', a: 'Richard Réti', p: 'Mestre e teórico do xadrez' },
  { t: 'Prefiro ganhar títulos com o time a ganhar prêmios individuais ou fazer mais gols do que qualquer um.', a: 'Lionel Messi', p: 'Campeão mundial de futebol' },
  { t: 'Quem não vê no jogo outro objetivo além de dar xeque-mate no adversário jamais será um bom enxadrista.', a: 'Max Euwe', p: 'Campeão mundial de xadrez' },
  { t: 'Há quem largue melhor do que eu, mas eu sou forte na chegada.', a: 'Usain Bolt', p: 'Octacampeão olímpico de atletismo' },
  { t: 'O xeque descoberto é o bombardeiro de mergulho do tabuleiro.', a: 'Reuben Fine', p: 'Grande mestre americano' },
  { t: 'Talento sem trabalho duro não é nada.', a: 'Cristiano Ronaldo', p: 'Cinco vezes melhor jogador de futebol do mundo' },
  { t: 'Quando estou em forma, meu estilo é um pouco teimoso, quase bruto. Às vezes sinto um grande espírito de luta que me impulsiona.', a: 'Boris Spassky', p: 'Campeão mundial de xadrez' },
  { t: 'Não fujo de um desafio por medo. Ao contrário, corro na direção dele, porque a única maneira de escapar do medo é pisoteá-lo.', a: 'Nadia Comaneci', p: 'Ginasta, primeira nota 10 olímpica' },
  { t: 'Quanto mais velho fico, mais valorizo os peões.', a: 'Paul Keres', p: 'Grande mestre estoniano' },
  { t: 'Você erra 100% dos arremessos que não tenta.', a: 'Wayne Gretzky', p: 'Lenda do hóquei no gelo' },
  { t: 'O xadrez é, eminente e enfaticamente, o jogo dos filósofos.', a: 'Paul Morphy', p: 'Lenda do xadrez' },
  { t: 'É querer mais, é treinar mais, é se cuidar mais, é estar pronta para jogar 90 mais 30 minutos e quantos mais minutos forem.', a: 'Marta', p: 'Seis vezes melhor jogadora de futebol do mundo' },
  { t: 'Meu estudo do xadrez foi acompanhado de uma forte atração pela música, e provavelmente foi graças a isso que me acostumei a pensar no xadrez como uma arte.', a: 'Vasily Smyslov', p: 'Campeão mundial de xadrez' },
  { t: 'A bola é redonda e o jogo dura 90 minutos.', a: 'Sepp Herberger', p: 'Técnico campeão mundial de futebol' },
  { t: 'Com o sucesso você não aprende absolutamente nada. Do fracasso e dos reveses é que se tiram conclusões. Isso vale tanto para a vida pessoal quanto para a carreira.', a: 'Niki Lauda', p: 'Tricampeão de Fórmula 1' },
  { t: 'Sempre digo que as mulheres devem ter a autoconfiança de que são tão boas quanto os homens, desde que estejam dispostas a trabalhar e a levar o jogo tão a sério quanto eles.', a: 'Judit Polgár', p: 'Melhor enxadrista mulher da história' },
  { t: 'O golfe de competição é jogado principalmente num campo de catorze centímetros: o espaço entre as suas orelhas.', a: 'Bobby Jones', p: 'Lenda do golfe' },
  { t: 'Os finais de peões estão para o xadrez como o putt está para o golfe.', a: 'Cecil Purdy', p: 'Campeão mundial de xadrez por correspondência' },
  { t: 'A vida não é um esporte para espectadores.', a: 'Jackie Robinson', p: 'Lenda do beisebol' },
  { t: 'O xadrez moderno se preocupa demais com coisas como estrutura de peões. Esqueça: o xeque-mate encerra a partida.', a: 'Nigel Short', p: 'Grande mestre inglês' },
  { t: 'Perdoo os jogadores que não acertam, mas não os que não se esforçam.', a: 'Pep Guardiola', p: 'Técnico de futebol multicampeão' },
  { t: 'Depois de 1.e4, o jogo das brancas está nos últimos suspiros.', a: 'Gyula Breyer', p: 'Mestre húngaro de xadrez' },
  { t: 'O futebol é um jogo simples, baseado em dar e receber passes, em dominar a bola e em se colocar disponível para receber. É terrivelmente simples.', a: 'Bill Shankly', p: 'Técnico lendário do Liverpool' },
  { t: 'Não é um lance, nem mesmo o melhor lance, que você deve procurar, mas um plano realizável.', a: 'Eugene Znosko-Borovsky', p: 'Mestre russo de xadrez' },
  { t: 'Não olhe para trás. Alguma coisa pode estar alcançando você.', a: 'Satchel Paige', p: 'Lenda do beisebol' },
  { t: 'Os peões são a alma do xadrez.', a: 'François-André Philidor', p: 'Maior enxadrista do século XVIII' },
  { t: 'Nunca fiz um gol na vida sem receber um passe de alguém.', a: 'Abby Wambach', p: 'Campeã mundial de futebol' },
  { t: 'Como enxadrista, é preciso saber controlar os sentimentos; é preciso ser frio como uma máquina.', a: 'Levon Aronian', p: 'Grande mestre, campeão da Copa do Mundo' },
  { t: 'A vontade de se preparar tem que ser maior do que a vontade de vencer. Vencer será consequência da boa preparação.', a: 'Bernardinho', p: 'Técnico campeão olímpico de vôlei' },
  { t: 'Depois de uma abertura ruim, há esperança no meio-jogo. Depois de um meio-jogo ruim, há esperança no final. Mas, quando você chega ao final, a hora da verdade chegou.', a: 'Edmar Mednis', p: 'Grande mestre americano' },
  { t: 'Você precisa acreditar em si mesma quando ninguém mais acredita. Isso já faz de você uma vencedora.', a: 'Venus Williams', p: 'Heptacampeã de Grand Slam no tênis' },
  { t: 'Quando jogo de brancas, ganho porque estou de brancas. Quando jogo de pretas, ganho porque sou Bogoljubov.', a: 'Efim Bogoljubov', p: 'Grande mestre de xadrez' },
  { t: 'A mente é tudo. Músculos são pedaços de borracha. Tudo o que sou, sou por causa da minha mente.', a: 'Paavo Nurmi', p: 'Nove ouros olímpicos no atletismo' },
  { t: 'A tacada mais importante do golfe é a próxima.', a: 'Ben Hogan', p: 'Lenda do golfe' },
  { t: 'Vença com elegância, perca com dignidade.', a: 'Susan Polgár', p: 'Campeã mundial de xadrez' },
  { t: 'Não desista. Nunca desista.', a: 'Jim Valvano', p: 'Técnico campeão de basquete' },
  { t: 'Bobby simplesmente solta as peças e elas caem nas casas certas.', a: 'Miguel Najdorf', p: 'Grande mestre argentino' },
  { t: 'Não importa quais conquistas você alcance, alguém ajudou você.', a: 'Althea Gibson', p: 'Pioneira do tênis' },
  { t: 'Todo mestre de xadrez já foi um dia um principiante.', a: 'Irving Chernev', p: 'Mestre e escritor de xadrez' },
  { t: 'O objetivo final do caratê não está na vitória nem na derrota, mas no aperfeiçoamento do caráter de seus praticantes.', a: 'Gichin Funakoshi', p: 'Fundador do caratê moderno' },
  { t: 'Em hipótese alguma jogue rápido se você tem uma posição ganha. Esqueça o relógio, use todo o seu tempo e faça bons lances.', a: 'Pal Benko', p: 'Grande mestre de xadrez' },
  { t: 'Meu ponto mais forte é a persistência. Nunca desisto numa partida. Por pior que esteja, luto até a última bola.', a: 'Björn Borg', p: 'Lenda do tênis' },
  { t: 'Um lance ruim anula quarenta bons.', a: 'Al Horowitz', p: 'Mestre internacional de xadrez' },
  { t: 'Meu país não me mandou a 5.000 milhas de distância para largar na prova; mandou-me a 5.000 milhas para terminar a prova.', a: 'John Stephen Akhwari', p: 'Maratonista olímpico da Tanzânia' },
  { t: 'Sessenta dias por ano eu jogo torneios, cinco dias descanso, e trezentos dias trabalho no meu jogo.', a: 'Akiba Rubinstein', p: 'Grande mestre polonês' },
  { t: 'Por que não se pode vencer um clube mais rico? Nunca vi um saco de dinheiro fazer um gol.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'Detesto os finais. Uma partida bem jogada deveria estar praticamente decidida no meio-jogo.', a: 'Dawid Janowski', p: 'Mestre de xadrez' },
  { t: 'Não existe mão santa, existe mão treinada.', a: 'Oscar Schmidt', p: 'Lenda do basquete brasileiro' },
  { t: 'Acredito que o xadrez possui uma magia que também ajuda na idade avançada. Um joelho reumático é esquecido durante uma partida de xadrez.', a: 'Vlastimil Hort', p: 'Grande mestre tcheco' },
  { t: 'Nunca fica mais fácil; você só fica mais rápido.', a: 'Greg LeMond', p: 'Tricampeão do Tour de France' },
  { t: 'Nenhum jogador é tão bom quanto todos juntos.', a: 'Alfredo Di Stéfano', p: 'Lenda do Real Madrid' },
  { t: 'Sua única tarefa na abertura é chegar a um meio-jogo jogável.', a: 'Lajos Portisch', p: 'Grande mestre húngaro' },
  { t: 'Seja rápido, mas não se apresse.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'O rei afogado é a tragicomédia do xadrez.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Se você está perdendo a fé na natureza humana, saia para assistir a uma maratona.', a: 'Kathrine Switzer', p: 'Pioneira da maratona feminina' },
  { t: 'É preciso ter espírito de luta. É preciso forçar os lances e correr riscos.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Você deve sempre se esforçar para ser o melhor, mas nunca deve acreditar que é.', a: 'Juan Manuel Fangio', p: 'Pentacampeão de Fórmula 1' },
  { t: 'No fim das contas, o que separa o vencedor do perdedor no nível dos grandes mestres é a disposição de fazer o impensável.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'O próximo ponto: é só nisso que você deve pensar.', a: 'Rod Laver', p: 'Lenda do tênis' },
  { t: 'O xadrez é 99% tática.', a: 'Richard Teichmann', p: 'Mestre alemão de xadrez' },
  { t: 'Se você faz o trabalho, é recompensado. Não existem atalhos na vida.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'Eu jogo contra as peças.', a: 'Svetozar Gligorić', p: 'Grande mestre sérvio' },
  { t: 'Tudo o que é negativo, pressão, desafios, é uma oportunidade para eu crescer.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'Lances tranquilos muitas vezes causam impressão mais forte do que uma combinação selvagem cheia de sacrifícios.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'O que fazer com um erro: reconheça, admita, aprenda com ele, esqueça.', a: 'Dean Smith', p: 'Técnico lendário de basquete' },
  { t: 'Não basta ser um bom jogador; é preciso também jogar bem.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Não temo ninguém, mas respeito todo mundo.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Normalmente faço o que a minha intuição manda. A maior parte do tempo que passo pensando é só para conferir.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Eu sou o maior. Eu dizia isso antes mesmo de saber que era.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'A medida de quem somos é o que fazemos com o que temos.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'Para melhorar o seu jogo, você deve estudar os finais antes de tudo, pois os finais podem ser estudados e dominados por si sós, enquanto o meio-jogo e a abertura devem ser estudados em relação ao final.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'Dá para observar muita coisa só olhando.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'Por meio do xadrez desenvolvi meu caráter. O xadrez ensina, antes de tudo, a ser objetivo. Só se chega a grande mestre enxergando os próprios erros e deficiências. Exatamente como na vida.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Não existem limites. Existem apenas platôs, e você não deve ficar neles; deve ir além.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'Uma vitória obtida com uma combinação incorreta, por mais vistosa que seja, me enche de horror artístico.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Sempre trabalho com um objetivo, e o objetivo é melhorar como jogador e como pessoa. Isso, no fim, é o mais importante de tudo.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'Para ser campeão é preciso mais do que ser simplesmente um jogador forte; é preciso ser também um ser humano forte.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'Acho que tudo é possível, desde que você se concentre nisso e dedique trabalho e tempo.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Quem está em ligeira desvantagem joga com mais atenção, inventividade e ousadia do que o adversário que relaxa ou se contenta com o empate.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'O esporte ensina caráter, ensina a jogar dentro das regras, ensina como é ganhar e perder. Ensina sobre a vida.', a: 'Billie Jean King', p: 'Lenda do tênis' },
  { t: 'A confiança é muito importante, até mesmo fingir confiança. Se você erra mas não deixa o adversário perceber o que está pensando, ele pode deixar passar o erro.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'Vencer não é o importante. Planejar e se preparar é que é crucial. Quando você planeja muito bem e se prepara muito bem, o sucesso pode vir pelo caminho.', a: 'Eliud Kipchoge', p: 'Bicampeão olímpico da maratona' },
  { t: 'A falta de paciência é provavelmente o motivo mais comum para se perder uma partida, ou para empatar partidas que deveriam ter sido ganhas.', a: 'Bent Larsen', p: 'Grande mestre dinamarquês' },
  { t: 'O sucesso é uma jornada, não um destino. O fazer muitas vezes é mais importante do que o resultado.', a: 'Arthur Ashe', p: 'Campeão de Wimbledon' },
  { t: 'No xadrez, tudo se apoia na tática. Se pensarmos na estratégia como um bloco de mármore, a tática é o cinzel com que o mestre trabalha para criar obras de arte.', a: 'Tigran Petrosian', p: 'Campeão mundial de xadrez' },
  { t: 'Tudo é treino.', a: 'Pelé', p: 'Rei do futebol' },
  { t: 'A arma mais poderosa no xadrez é ter o próximo lance.', a: 'David Bronstein', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Se você quer correr, corra uma milha. Se quer experimentar uma vida diferente, corra uma maratona.', a: 'Emil Zátopek', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Prefiro me arrepender dos riscos que não deram certo a me arrepender das chances que não aproveitei.', a: 'Simone Biles', p: 'Campeã olímpica de ginástica' },
  { t: 'O xadrez é um conto de fadas de 1001 erros.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Uma vida inteira de treino por apenas dez segundos.', a: 'Jesse Owens', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Xadrez é vida.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Acredito mesmo que um campeão se define não pelas vitórias, mas pela forma como se recupera quando cai.', a: 'Serena Williams', p: 'Lenda do tênis' },
  { t: 'No xadrez não se pode controlar tudo. Às vezes a partida toma um rumo inesperado, e a beleza começa a surgir. Os dois jogadores sempre contribuem para isso.', a: 'Vladimir Kramnik', p: 'Campeão mundial de xadrez' },
  { t: 'Se você quer ser bem-sucedido, precisa ter dedicação total, buscar seu último limite e dar o melhor de si.', a: 'Ayrton Senna', p: 'Tricampeão de Fórmula 1' },
  { t: 'Via de regra, quanto mais erros há numa partida, mais memorável ela se torna, porque você sofreu e se preocupou com cada erro diante do tabuleiro.', a: 'Viktor Korchnoi', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'O que conta é o que você aprende depois de já saber tudo.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Reveses e derrotas são inevitáveis e essenciais para quem quer melhorar e se tornar um bom, ou mesmo um grande, competidor.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'É preciso chutar, senão não dá para fazer gol.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'A maestria no xadrez consiste, essencialmente, em analisar as posições com precisão.', a: 'Mikhail Botvinnik', p: 'Campeão mundial de xadrez' },
  { t: 'É o jeito como o time joga em conjunto que determina o seu sucesso. Você pode ter o maior grupo de estrelas do mundo, mas, se elas não jogarem juntas, o clube não valerá um centavo.', a: 'Babe Ruth', p: 'Lenda do beisebol' },
  { t: 'O xadrez era a língua materna de Capablanca.', a: 'Richard Réti', p: 'Mestre e teórico do xadrez' },
  { t: 'Preocupar-se não leva a lugar nenhum. Se você chega preocupado com o seu desempenho, já perdeu. Treine duro, apareça, corra o seu melhor e o resto se resolve sozinho.', a: 'Usain Bolt', p: 'Octacampeão olímpico de atletismo' },
  { t: 'Jogue a abertura como um livro, o meio-jogo como um mágico e o final como uma máquina.', a: 'Rudolf Spielmann', p: 'Mestre austríaco de xadrez' },
  { t: 'Minha atitude é: se você me empurra na direção de algo que acha ser uma fraqueza minha, eu transformo essa suposta fraqueza em força.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'O xadrez, como o amor, como a música, tem o poder de fazer as pessoas felizes.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Vencer é ótimo, claro, mas, se você quer mesmo fazer algo na vida, o segredo é aprender a perder. Ninguém fica invicto o tempo todo.', a: 'Wilma Rudolph', p: 'Tricampeã olímpica de atletismo' },
  { t: 'Se você tem medo de fracassar, provavelmente vai fracassar.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'O peão passado é um criminoso que deve ser mantido a sete chaves. Medidas brandas, como a vigilância policial, não bastam.', a: 'Aron Nimzowitsch', p: 'Mestre e teórico do xadrez' },
  { t: 'Não há como fugir do trabalho duro. Abrace-o.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Eles só podem capturar uma peça de cada vez!', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Eu me preocupo mais em ser uma boa pessoa do que em ser o melhor jogador do mundo.', a: 'Lionel Messi', p: 'Campeão mundial de futebol' },
  { t: 'Tento vencer o cara sentado à minha frente e escolher os lances mais desagradáveis para ele e para o estilo dele.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Cometemos erros errados demais.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'As combinações sempre foram o aspecto mais fascinante do xadrez. Os mestres as procuram, o público as aplaude, os críticos as elogiam.', a: 'Reuben Fine', p: 'Grande mestre americano' },
  { t: 'Depois que você aprende a desistir, isso vira hábito.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'Os livros de xadrez devem ser usados como usamos os óculos: para auxiliar a visão. Mas alguns jogadores os usam como se achassem que eles conferem a visão.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'Estou construindo uma fogueira, e a cada dia de treino ponho mais lenha. No momento certo, acendo o fósforo.', a: 'Mia Hamm', p: 'Bicampeã mundial de futebol' },
  { t: 'A combinação é a alma do xadrez.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Por maior que seja a sua dedicação, você nunca ganha nada sozinho.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'No tabuleiro de xadrez, a mentira e a hipocrisia não sobrevivem por muito tempo.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'Flutue como uma borboleta, ferroe como uma abelha.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'Tática é saber o que fazer quando há algo a fazer; estratégia é saber o que fazer quando não há nada a fazer.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Se você acha que já é perfeito, nunca será.', a: 'Cristiano Ronaldo', p: 'Cinco vezes melhor jogador de futebol do mundo' },
  { t: 'Para mim, perder uma partida de tênis não é fracasso, é pesquisa.', a: 'Billie Jean King', p: 'Lenda do tênis' },
  { t: 'A estratégia exige reflexão; a tática exige observação.', a: 'Max Euwe', p: 'Campeão mundial de xadrez' },
  { t: 'Não é um aumento diário, mas uma diminuição diária. Corte o que não é essencial.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'Memória forte, concentração, imaginação e muita força de vontade: é o que se exige para ser um grande enxadrista.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'O trabalho duro tornou tudo fácil. Esse é o meu segredo. É por isso que eu venço.', a: 'Nadia Comaneci', p: 'Ginasta, primeira nota 10 olímpica' },
  { t: 'Se você deseja ter sucesso, precisa enfrentar o risco do fracasso.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Não deixe que o que você não pode fazer atrapalhe o que você pode fazer.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Estude as partidas dos grandes enxadristas, mas não as engula inteiras. Elas valem não pelos lances isolados, mas pela visão de xadrez, pela maneira de pensar.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'Se você diz \'não consigo\', está limitando o que pode fazer ou o que um dia fará.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Não é preciso jogar bem; basta jogar melhor do que o adversário.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Com o que recebemos, ganhamos o sustento; com o que damos, construímos uma vida.', a: 'Arthur Ashe', p: 'Campeão de Wimbledon' },
  { t: 'Se a revanche motiva você, vá em frente! Mas o principal é colocar o seu jogo em ordem.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'Toda desvantagem tem a sua vantagem.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'O xadrez não é para almas tímidas.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Para ter sucesso você precisa ser egoísta, senão nunca conquista nada. E, quando chega ao seu nível mais alto, aí precisa ser generoso.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'Tenha a coragem das suas convicções. Se você acha que o seu lance é bom, jogue-o.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'O pênalti é uma maneira covarde de fazer gol.', a: 'Pelé', p: 'Rei do futebol' },
  { t: 'Não sou nenhuma aberração. Posso ser muito bom no xadrez, mas sou apenas uma pessoa normal.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Uma competição bem-sucedida, para mim, é sempre entrar lá e dar 100% no que estou fazendo. Nem sempre é vencer.', a: 'Simone Biles', p: 'Campeã olímpica de ginástica' },
  { t: 'Depois do jogo é antes do jogo.', a: 'Sepp Herberger', p: 'Técnico campeão mundial de futebol' },
  { t: 'A essência do xadrez é pensar sobre o que o xadrez é.', a: 'David Bronstein', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Grandes coisas vêm do trabalho duro e da perseverança. Sem desculpas.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'O xadrez, antes de tudo, é arte.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Nenhum ser humano é limitado.', a: 'Eliud Kipchoge', p: 'Bicampeão olímpico da maratona' },
  { t: 'Dizem que as minhas partidas deveriam ser mais interessantes. Eu poderia ser mais interessante... e também perder.', a: 'Tigran Petrosian', p: 'Campeão mundial de xadrez' },
  { t: 'Sempre acreditei que, se você está num buraco e as coisas não vão bem, você sairá dele mais forte. Tudo na vida é assim.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'O melhor indicador da forma de um enxadrista é a sua capacidade de sentir o clímax da partida.', a: 'Boris Spassky', p: 'Campeão mundial de xadrez' },
  { t: 'Não gosto de perder, em nada; e, no entanto, cresci mais com os reveses do que com as vitórias.', a: 'Serena Williams', p: 'Lenda do tênis' },
  { t: 'Antes do final, os deuses colocaram o meio-jogo.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'O futuro não é mais o que costumava ser.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'O estômago é parte essencial do mestre de xadrez.', a: 'Bent Larsen', p: 'Grande mestre dinamarquês' },
  { t: 'Não dá para subir ao segundo andar sem escada. Quando você mira alto demais e não alcança, o entusiasmo vira amargura. Busque uma meta razoável e vá elevando aos poucos.', a: 'Emil Zátopek', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'O xadrez é como a musculação. Se você treina todos os dias, fica em plena forma. Com o cérebro é igual: o xadrez é questão de treino diário.', a: 'Vladimir Kramnik', p: 'Campeão mundial de xadrez' },
  { t: 'É a falta de fé que faz as pessoas terem medo de enfrentar desafios, e eu acreditei em mim mesmo.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'Para me vencer, é preciso me derrotar três vezes: na abertura, no meio-jogo e no final.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Faça de cada dia a sua obra-prima.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Alguma parte de um erro está sempre correta.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'A diferença entre uma pessoa bem-sucedida e as outras não é falta de força nem falta de conhecimento, mas falta de vontade.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'Valorizem mais. Chorem no começo para sorrir no fim.', a: 'Marta', p: 'Seis vezes melhor jogadora de futebol do mundo' },
  { t: 'É disso que se trata o xadrez. Um dia você dá uma lição ao adversário, no dia seguinte é ele quem dá uma lição em você.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Eu sou parte de uma equipe. Então, quando venço, não sou eu apenas quem vence. De certa forma, termino o trabalho de um grupo enorme de pessoas.', a: 'Ayrton Senna', p: 'Tricampeão de Fórmula 1' },
  { t: 'Questione o status quo o tempo todo, principalmente quando as coisas vão bem.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Todos nós temos sonhos. Mas, para transformar sonhos em realidade, é preciso muita determinação, dedicação, autodisciplina e esforço.', a: 'Jesse Owens', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Sem erro não pode haver brilhantismo.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'Não é hora de procurar desculpas.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'Xadrez não se aprende, xadrez se entende.', a: 'Viktor Korchnoi', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Os home runs de ontem não ganham os jogos de hoje.', a: 'Babe Ruth', p: 'Lenda do beisebol' },
  { t: 'O xadrez é 30 a 40% psicologia. Isso não existe quando você joga contra um computador. Eu não consigo confundi-lo.', a: 'Judit Polgár', p: 'Melhor enxadrista mulher da história' },
  { t: 'Se eu quisesse que você entendesse, teria explicado melhor.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'Um bom jogador sempre tem sorte.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'Algumas pessoas acham que o futebol é questão de vida ou morte. Posso garantir que é muito, muito mais importante do que isso.', a: 'Bill Shankly', p: 'Técnico lendário do Liverpool' },
  { t: 'Tudo está em constante mudança, e isso inclui o mundo do xadrez.', a: 'Mikhail Botvinnik', p: 'Campeão mundial de xadrez' },
  { t: 'Sempre acreditei que, se você se dedicar ao trabalho, os resultados virão.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'Mais tarde comecei a ter sucesso nas partidas decisivas. Talvez por ter percebido uma verdade muito simples: não era só eu que estava nervoso, meu adversário também.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Acho que o autoconhecimento é provavelmente o mais importante para se tornar campeão.', a: 'Billie Jean King', p: 'Lenda do tênis' },
  { t: 'Fico mais chateado quando perco em outras coisas do que no xadrez. Sempre fico chateado quando perco no Banco Imobiliário.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Farei o que for preciso para vencer: sentar no banco agitando uma toalha, entregar um copo d\'água a um companheiro ou acertar o arremesso da vitória.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'No futebol, o pior são as desculpas. Desculpas significam que você não pode crescer nem avançar.', a: 'Pep Guardiola', p: 'Técnico de futebol multicampeão' },
  { t: 'Posso ser um leão velho, mas ainda arranco a mão de quem a colocar na minha boca.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Uma vida só é importante pelo impacto que tem em outras vidas.', a: 'Jackie Robinson', p: 'Lenda do beisebol' },
  { t: 'Gosto muito de 1.e4, mas meus resultados com 1.d4 são melhores.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'Não dá para colocar limite em nada. Quanto mais você sonha, mais longe chega.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Muitos se tornaram mestres de xadrez; ninguém se tornou o mestre do xadrez.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Esvazie a mente. Seja sem forma, sem contorno, como a água. Seja água, meu amigo.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'Para mim o xadrez não é um jogo, mas uma arte. Sim, e assumo todas as responsabilidades que uma arte impõe aos seus adeptos.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Energia negativa é energia desperdiçada.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Para não perder uma peça, muita gente já perdeu a partida.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Ninguém ganha um jogo sozinho.', a: 'Pelé', p: 'Rei do futebol' },
  { t: 'Em qualquer partida há poucos momentos críticos em que não existe segunda melhor decisão. O resto dos lances é intuitivo.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'Muita gente critica a Fórmula 1 como um risco desnecessário. Mas como seria a vida se só fizéssemos o que é necessário?', a: 'Niki Lauda', p: 'Tricampeão de Fórmula 1' },
  { t: 'A tática flui de uma posição superior.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Sucesso é a paz de espírito que resulta diretamente da satisfação de saber que você se esforçou para ser o melhor que é capaz de ser.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Não basta ter talento. Não basta trabalhar duro e estudar até tarde da noite. Você também precisa conhecer intimamente os métodos que usa para tomar suas decisões.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Não se alcança o triunfo sem a luta.', a: 'Wilma Rudolph', p: 'Tricampeã olímpica de atletismo' },
  { t: 'Por mais desesperadora que a situação pareça, sempre existe a possibilidade de oferecer uma resistência tenaz.', a: 'Paul Keres', p: 'Grande mestre estoniano' },
  { t: 'Não acabou até acabar.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'Errei mais de 9.000 arremessos na carreira. Perdi quase 300 jogos. Em 26 ocasiões confiaram a mim o arremesso da vitória e eu errei. Fracassei muitas e muitas vezes na vida. E é por isso que tenho sucesso.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'Ajude as suas peças para que elas possam ajudar você.', a: 'Paul Morphy', p: 'Lenda do xadrez' },
  { t: 'O maior elogio que você pode me fazer é dizer que trabalho duro todos os dias.', a: 'Wayne Gretzky', p: 'Lenda do hóquei no gelo' },
  { t: 'Não conseguimos resistir ao fascínio do sacrifício, pois a paixão pelos sacrifícios faz parte da natureza do enxadrista.', a: 'Rudolf Spielmann', p: 'Mestre austríaco de xadrez' },
  { t: 'Uma chave importante para o sucesso é a autoconfiança. Uma chave importante para a autoconfiança é a preparação.', a: 'Arthur Ashe', p: 'Campeão de Wimbledon' },
  { t: 'É do meu estilo levar o adversário e a mim mesmo para terrenos desconhecidos. Uma partida de xadrez não é uma prova de conhecimento; é uma batalha de nervos.', a: 'David Bronstein', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Conhecer a mente é tão importante quanto entender o corpo.', a: 'Usain Bolt', p: 'Octacampeão olímpico de atletismo' },
  { t: 'Transformar o xadrez em pôquer e torcer por um blefe não faz parte das minhas convicções.', a: 'Tigran Petrosian', p: 'Campeão mundial de xadrez' },
  { t: 'Só quem sabe o que é ser derrotado consegue descer ao fundo da alma e voltar com aquele grama a mais de força necessário para vencer quando a luta está igual.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'No xadrez, como na vida, o adversário mais perigoso de um homem é ele mesmo.', a: 'Vasily Smyslov', p: 'Campeão mundial de xadrez' },
  { t: 'A perfeição não é alcançável, mas, se perseguirmos a perfeição, podemos alcançar a excelência.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'O conhecimento da combinação é o alicerce do jogo posicional.', a: 'Richard Réti', p: 'Mestre e teórico do xadrez' },
  { t: 'Não sou a próxima Usain Bolt nem a próxima Michael Phelps. Sou a primeira Simone Biles.', a: 'Simone Biles', p: 'Campeã olímpica de ginástica' },
  { t: 'A zombaria pode muito, como amargar a existência de jovens talentos; mas uma coisa ela não consegue: deter para sempre a chegada de ideias novas e poderosas.', a: 'Aron Nimzowitsch', p: 'Mestre e teórico do xadrez' },
  { t: 'O fracasso acontece o tempo todo. Acontece todos os dias no treino. O que faz você melhorar é como reage a ele.', a: 'Mia Hamm', p: 'Bicampeã mundial de futebol' },
  { t: 'Claro que os erros não fazem bem a uma partida de xadrez, mas são inevitáveis; e, de todo modo, uma partida sem nenhum erro, a tal \'partida impecável\', é incolor.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Você tem que lutar para alcançar o seu sonho. Tem que se sacrificar e trabalhar duro por ele.', a: 'Lionel Messi', p: 'Campeão mundial de futebol' },
  { t: '100% de mim não é nada comparado a 1% de toda a equipe.', a: 'Eliud Kipchoge', p: 'Bicampeão olímpico da maratona' },
  { t: 'Se você joga a Caro-Kann quando jovem, o que vai jogar quando ficar velho?', a: 'Bent Larsen', p: 'Grande mestre dinamarquês' },
  { t: 'Futebol se joga com a cabeça; as pernas estão lá para ajudar.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'Se você quer chegar ao topo, sempre existe o risco de se isolar das outras pessoas.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Você ganha algumas, perde outras, e algumas são canceladas pela chuva. Mas precisa se uniformizar para todas.', a: 'Satchel Paige', p: 'Lenda do beisebol' },
  { t: 'Quanto mais fraco o jogador, mais terrível o cavalo é para ele; mas, à medida que o jogador fica mais forte, o valor do bispo se torna mais evidente.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'Nunca aprendi nada com uma partida que venci.', a: 'Bobby Jones', p: 'Lenda do golfe' },
  { t: 'Tudo o que eu quero fazer, sempre, é jogar xadrez.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Perder não é meu inimigo. O medo de perder é meu inimigo.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'O xadrez é, acima de tudo, uma luta.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'O que passou já está encerrado. O que acho mais interessante é o que ainda está por vir.', a: 'Emil Zátopek', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Um peão isolado espalha melancolia por todo o tabuleiro.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Eu posso aceitar o fracasso; todo mundo fracassa em alguma coisa. Mas não posso aceitar não tentar.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'O xadrez é um jogo infinitamente complexo, que se pode jogar de maneiras infinitamente numerosas e variadas.', a: 'Vladimir Kramnik', p: 'Campeão mundial de xadrez' },
  { t: 'O tênis é só um jogo; a família é para sempre.', a: 'Serena Williams', p: 'Lenda do tênis' },
  { t: 'O xadrez é parte da cultura, e se uma cultura entra em declínio, o xadrez também declina.', a: 'Mikhail Botvinnik', p: 'Campeão mundial de xadrez' },
  { t: 'O momento em que você desiste é o momento em que deixa outra pessoa vencer.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'Vencer não é um segredo que pertence a poucos. É algo que podemos aprender estudando a nós mesmos, estudando o ambiente e nos preparando para qualquer desafio.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'As coisas saem melhor para quem tira o melhor de como as coisas saem.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'É apenas um ponto.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Qual é o objetivo de jogar um gambito? Ganhar fama de jogador arrojado ao custo de perder a partida.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'A pressão é um privilégio.', a: 'Billie Jean King', p: 'Lenda do tênis' },
  { t: 'Alekhine é um poeta que cria uma obra de arte a partir de algo que mal inspiraria outro homem a mandar um cartão-postal para casa.', a: 'Max Euwe', p: 'Campeão mundial de xadrez' },
  { t: 'No que diz respeito ao empenho, ao compromisso, ao esforço, à dedicação, não existe meio-termo. Ou você faz uma coisa bem feita ou não faz.', a: 'Ayrton Senna', p: 'Tricampeão de Fórmula 1' },
  { t: 'Jogar nos dois lados do tabuleiro é a minha estratégia favorita.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Uma meta nem sempre existe para ser alcançada; muitas vezes serve simplesmente como algo para se mirar.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'O xadrez é tão inspirador que não acredito que um bom jogador seja capaz de ter um mau pensamento durante a partida.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Quero poder olhar para trás e dizer: \'Fiz tudo o que pude e tive sucesso.\' Não quero olhar para trás e dizer que deveria ter feito isso ou aquilo.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Gosto de induzir meus adversários a atacar, de deixá-los provar a alegria da iniciativa, para que se empolguem, fiquem descuidados e sacrifiquem material.', a: 'Viktor Korchnoi', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Se você não sabe para onde está indo, pode acabar chegando a outro lugar.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'Os peões não apenas criam o esboço de toda a pintura; eles são também o solo, o alicerce de qualquer posição.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'As batalhas que contam não são as das medalhas de ouro. As lutas dentro de você, as batalhas invisíveis e inevitáveis dentro de cada um de nós: é aí que está tudo.', a: 'Jesse Owens', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Enquanto meu adversário não tiver rocado, a cada lance eu procuro um pretexto para atacar.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Aproveite a jornada e tente melhorar a cada dia. E não perca a paixão e o amor pelo que você faz.', a: 'Nadia Comaneci', p: 'Ginasta, primeira nota 10 olímpica' },
  { t: 'A intuição no xadrez pode ser definida como o primeiro lance que vem à cabeça quando você vê uma posição.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'Entusiasmo é tudo. Ele deve estar esticado e vibrando como uma corda de violão.', a: 'Pelé', p: 'Rei do futebol' },
  { t: 'Prefiro ter um peão a mais do que um dedo.', a: 'Reuben Fine', p: 'Grande mestre americano' },
  { t: 'Não sou perfeccionista, mas gosto de sentir que as coisas são bem feitas. Mais importante do que isso, sinto uma necessidade sem fim de aprender, de melhorar, de evoluir.', a: 'Cristiano Ronaldo', p: 'Cinco vezes melhor jogador de futebol do mundo' },
  { t: 'A prática não leva à perfeição. Só a prática perfeita leva à perfeição.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'Comecei simplesmente sentado diante do tabuleiro, explorando. No começo eu nem tinha livros, jogava sozinho. Aprendi muito com isso.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Cada strike me deixa mais perto do próximo home run.', a: 'Babe Ruth', p: 'Lenda do beisebol' },
  { t: 'Aprende-se muito mais com uma partida perdida do que com uma vencida. Você terá de perder centenas de partidas antes de se tornar um bom jogador.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'Um homem que vê o mundo aos cinquenta do mesmo jeito que via aos vinte desperdiçou trinta anos de vida.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'Ninguém jamais ganhou uma partida abandonando.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Velocidade costuma ser confundida com visão de jogo. Quando eu começo a correr antes dos outros, pareço mais rápido.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'Alguns acham que sou cauteloso demais quando jogo. Eu procuro evitar o acaso. Quem confia no acaso deveria jogar cartas ou roleta.', a: 'Tigran Petrosian', p: 'Campeão mundial de xadrez' },
  { t: 'Nunca diga nunca, porque os limites, assim como os medos, muitas vezes são apenas uma ilusão.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'O xadrez exige concentração total.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'O principal ingrediente do estrelato é o resto do time.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'A capacidade de trabalhar duro por dias a fio sem perder o foco é um talento. A capacidade de continuar absorvendo informação nova depois de muitas horas de estudo é um talento.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Aquelas vezes em que você acorda cedo e trabalha duro, em que fica até tarde e trabalha duro, em que não está com vontade, está cansado demais, mas faz mesmo assim: esse é, na verdade, o sonho.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'Perder a objetividade diante de uma posição quase sempre significa arruinar a partida.', a: 'David Bronstein', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'A vida é maior do que a quadra.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Sempre sinto um pouco de pena de quem não conhece o xadrez, assim como teria pena de quem nunca conheceu o amor.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'A glória é ser feliz. A glória não é ganhar aqui ou ali. A glória é treinar, aproveitar cada dia, gostar de trabalhar duro, tentar ser um jogador melhor do que antes.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'Estar apurado no relógio, a meu ver, vale tão pouco como desculpa quanto a alegação do infrator de que estava bêbado quando cometeu o crime.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Você nunca está realmente jogando contra um adversário. Está jogando contra si mesmo, contra os seus padrões mais altos; e, quando alcança os seus limites, essa é a verdadeira alegria.', a: 'Arthur Ashe', p: 'Campeão de Wimbledon' },
  { t: 'O treino cria confiança. A confiança dá força a você.', a: 'Simone Biles', p: 'Campeã olímpica de ginástica' },
  { t: 'Até o rei mais preguiçoso foge desesperado diante de um xeque duplo.', a: 'Aron Nimzowitsch', p: 'Mestre e teórico do xadrez' },
  { t: 'Quanto mais difícil a vitória, maior a felicidade de vencer.', a: 'Pelé', p: 'Rei do futebol' },
  { t: 'Vejo as combinações tão bem quanto Alekhine, mas não consigo chegar às mesmas posições.', a: 'Rudolf Spielmann', p: 'Mestre austríaco de xadrez' },
  { t: 'O atletismo não tem tanto a ver com as pernas. Tem a ver com o coração e a mente.', a: 'Eliud Kipchoge', p: 'Bicampeão olímpico da maratona' },
  { t: 'Jogar pelo empate, pelo menos de brancas, é até certo ponto um crime contra o xadrez.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Quando chegar a uma bifurcação na estrada, pegue-a.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'As leis do xadrez não permitem livre escolha: você tem de jogar, queira ou não.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'Qualidade sem resultado não serve para nada. Resultado sem qualidade é chato.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'O xadrez é uma bela amante.', a: 'Bent Larsen', p: 'Grande mestre dinamarquês' },
  { t: 'Um atleta não pode correr com dinheiro nos bolsos. Ele deve correr com esperança no coração e sonhos na cabeça.', a: 'Emil Zátopek', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Sem o elemento do prazer, não vale a pena tentar ser excelente em nada.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'Se você quer ser o melhor, precisa fazer coisas que os outros não estão dispostos a fazer.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Você só fica bom no xadrez se amar o jogo.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Você precisa esperar grandes coisas de si mesmo antes de poder realizá-las.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'É sempre melhor sacrificar as peças do adversário.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Sou parte de um time, confio no time, cedo a ele e me sacrifico por ele, porque o time, e não o indivíduo, é o verdadeiro campeão.', a: 'Mia Hamm', p: 'Bicampeã mundial de futebol' },
  { t: 'Absorva o que é útil, descarte o que é inútil e acrescente o que é especificamente seu.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'O rei é uma peça de luta. Use-o!', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Eu não penso em limites.', a: 'Usain Bolt', p: 'Octacampeão olímpico de atletismo' },
  { t: 'Estou convencido de que a maneira de jogar xadrez sempre reflete a personalidade do jogador. Se algo define o seu caráter, também definirá o seu jeito de jogar.', a: 'Vladimir Kramnik', p: 'Campeão mundial de xadrez' },
  { t: 'Nunca subestime o poder dos sonhos e a influência do espírito humano. O potencial para a grandeza vive dentro de cada um de nós.', a: 'Wilma Rudolph', p: 'Tricampeã olímpica de atletismo' },
  { t: 'A partida pode ser dividida em três partes: a abertura, o meio-jogo e o final. Há uma coisa pela qual você deve se esforçar: ser igualmente eficiente nas três.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'A sorte não tem nada a ver com isso. Passei muitas e muitas horas, horas incontáveis, na quadra, trabalhando pelo meu momento, sem saber quando ele chegaria.', a: 'Serena Williams', p: 'Lenda do tênis' },
  { t: 'Estilo? Eu não tenho estilo.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'O preço do sucesso é trabalho duro, dedicação à tarefa e a determinação de que, ganhando ou perdendo, demos o melhor de nós.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'O xadrez é a arte da análise.', a: 'Mikhail Botvinnik', p: 'Campeão mundial de xadrez' },
  { t: 'O dia em que você achar que não há mais nada a melhorar será um dia triste para qualquer jogador.', a: 'Lionel Messi', p: 'Campeão mundial de futebol' },
  { t: 'O xadrez ajuda a se concentrar e a melhorar a lógica. Ensina a jogar dentro das regras e a assumir a responsabilidade pelos próprios atos.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Campeões não são feitos em academias. Campeões são feitos de algo que têm bem lá no fundo: um desejo, um sonho, uma visão.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'A desconfiança é a característica mais necessária do enxadrista.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Se você não está cometendo erros, é porque não está fazendo nada. Tenho certeza de que quem faz comete erros.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'O xadrez é como uma língua, e os melhores jogadores são muito fluentes nela. O talento pode ser desenvolvido cientificamente, mas primeiro você precisa descobrir em que é bom.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'Seja ousada. Se for para errar, erre feio, e não tenha medo de bater na bola.', a: 'Billie Jean King', p: 'Lenda do tênis' },
  { t: 'É preciso ceder casas para conquistar casas.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'No tênis, a perfeição é impossível. Das 1.526 partidas de simples que joguei na carreira, venci quase 80%. Mas ganhei apenas 54% dos pontos.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Eu não tenho ídolos. Tenho admiração por trabalho, dedicação e competência.', a: 'Ayrton Senna', p: 'Tricampeão de Fórmula 1' },
  { t: 'O xadrez será sempre o mestre de todos nós.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'O mais importante é tentar inspirar as pessoas para que elas possam ser grandes naquilo que quiserem fazer.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'Existem dois tipos de sacrifício: os corretos e os meus.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Encontre o que há de bom. Está por toda parte. Encontre, mostre, e você começará a acreditar nisso.', a: 'Jesse Owens', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Eu não estudo; eu crio.', a: 'Viktor Korchnoi', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Durante toda a minha carreira aprendi a gostar de sofrer.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'A partida mais difícil de ganhar é a partida ganha.', a: 'Emanuel Lasker', p: 'Campeão mundial de xadrez' },
  { t: 'Algumas pessoas querem que aconteça, outras desejam que aconteça, outras fazem acontecer.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'O xadrez é um jogo pela forma, uma arte pelo conteúdo e um esporte pela dificuldade de se alcançar a maestria.', a: 'Tigran Petrosian', p: 'Campeão mundial de xadrez' },
  { t: 'Odiei cada minuto de treino, mas dizia a mim mesmo: \'Não desista. Sofra agora e viva o resto da vida como campeão.\'', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'Uma partida de xadrez tem três fases: a primeira, quando você espera ter a vantagem; a segunda, quando acredita ter a vantagem; e a terceira, quando sabe que vai perder!', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Só existe uma bola, então você precisa ter a posse dela.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'Algumas pessoas acham que, se o adversário joga uma partida bonita, tudo bem perder. Eu não. É preciso ser implacável.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'É como um déjà vu, tudo de novo.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'O xadrez é um jogo muito lógico, e é quem consegue raciocinar de forma mais lógica e profunda que deve vencer.', a: 'José Raúl Capablanca', p: 'Campeão mundial de xadrez' },
  { t: 'As coisas não vão sair perfeitas. O que importa é como você se adapta e aprende com os erros.', a: 'Michael Phelps', p: 'Maior medalhista olímpico da história' },
  { t: 'Se você cometeu um erro ou uma imprecisão, não há por que se irritar e achar que tudo está perdido. É preciso se reorientar depressa e encontrar um novo plano na nova situação.', a: 'David Bronstein', p: 'Grande mestre, vice-campeão mundial' },
  { t: 'Não sei onde ficam os limites, mas gostaria de ir até lá.', a: 'Eliud Kipchoge', p: 'Bicampeão olímpico da maratona' },
  { t: 'Comece onde você está. Use o que você tem. Faça o que você pode.', a: 'Arthur Ashe', p: 'Campeão de Wimbledon' },
  { t: 'O xadrez é ginástica intelectual.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Se você não tem tempo para fazer direito, quando terá tempo para refazer?', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Quem tem medo de um peão da dama isolado deveria desistir do xadrez.', a: 'Siegbert Tarrasch', p: 'Mestre alemão de xadrez' },
  { t: 'Confiança é contagiosa. A falta de confiança também.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'O xadrez é tudo: arte, ciência e esporte.', a: 'Anatoly Karpov', p: 'Campeão mundial de xadrez' },
  { t: 'Os erros são sempre perdoáveis, se a pessoa tem a coragem de admiti-los.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'Seguindo à risca a regra de Botvinnik de analisar a fundo as próprias partidas, percebi com os anos que esse é o alicerce do desenvolvimento contínuo da maestria no xadrez.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Depois que você conhece o gosto do fracasso, a determinação corre atrás do sucesso.', a: 'Kobe Bryant', p: 'Lenda do basquete' },
  { t: 'Meus adversários também fazem bons lances. Às vezes eu não levo isso em consideração.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Quando uma pessoa treina uma vez, nada acontece. Quando se obriga a fazer uma coisa cem ou mil vezes, com certeza se desenvolve em mais sentidos do que o físico.', a: 'Emil Zátopek', p: 'Tetracampeão olímpico de atletismo' },
  { t: 'Para mim, o xadrez é ao mesmo tempo um jogo, um esporte, uma ciência e uma arte. E talvez até mais do que isso.', a: 'Bent Larsen', p: 'Grande mestre dinamarquês' },
  { t: '\'Sem esforço\' é um mito.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Você deve levar o adversário a uma floresta escura e profunda, onde 2+2=5 e o caminho de saída só tem largura para um.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'O talento vence jogos, mas o trabalho em equipe e a inteligência vencem campeonatos.', a: 'Michael Jordan', p: 'Lenda do basquete' },
  { t: 'Acredito que a verdadeira beleza do xadrez é mais do que suficiente para satisfazer todas as exigências possíveis.', a: 'Alexander Alekhine', p: 'Campeão mundial de xadrez' },
  { t: 'Com a bola, você deve deixar o campo o maior possível; sem a bola, o menor possível.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'Os erros estão todos lá no tabuleiro, esperando para serem cometidos.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'É a repetição de afirmações que leva à crença. E, quando essa crença se torna uma convicção profunda, as coisas começam a acontecer.', a: 'Muhammad Ali', p: 'Lenda do boxe' },
  { t: 'O que importa não é se você é derrubado, é se você se levanta.', a: 'Vince Lombardi', p: 'Técnico lendário de futebol americano' },
  { t: 'Hoje em dia, se você não é grande mestre aos 14 anos, pode esquecer.', a: 'Viswanathan Anand', p: 'Pentacampeão mundial de xadrez' },
  { t: 'Resistir significa aceitar. Aceitar as coisas como são e não como você gostaria que fossem, e então olhar para a frente, não para trás.', a: 'Rafael Nadal', p: 'Lenda do tênis' },
  { t: 'A autoconfiança é muito importante. Se você não acredita que pode vencer, tomará decisões covardes nos momentos cruciais, por puro respeito ao adversário.', a: 'Magnus Carlsen', p: 'Campeão mundial de xadrez' },
  { t: 'O beisebol é 90% mental. A outra metade é física.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
  { t: 'Só o jogador que tem a iniciativa tem o direito de atacar.', a: 'Wilhelm Steinitz', p: 'Primeiro campeão mundial de xadrez' },
  { t: 'Ao diabo com as circunstâncias; eu crio oportunidades.', a: 'Bruce Lee', p: 'Lenda das artes marciais' },
  { t: 'O xadrez é uma questão de julgamento delicado: saber quando golpear e como se esquivar.', a: 'Bobby Fischer', p: 'Campeão mundial de xadrez' },
  { t: 'Preocupe-se mais com o seu caráter do que com a sua reputação, porque o caráter é o que você realmente é, enquanto a reputação é apenas o que os outros pensam que você é.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Gosto de tomar a iniciativa e não dar paz de espírito ao meu adversário.', a: 'Mikhail Tal', p: 'Campeão mundial de xadrez' },
  { t: 'Jogar futebol é muito simples, mas jogar um futebol simples é a coisa mais difícil que existe.', a: 'Johan Cruyff', p: 'Lenda do futebol holandês' },
  { t: 'O xadrez é a vida em miniatura. O xadrez é luta, o xadrez são batalhas.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Às vezes você precisa aceitar que o outro jogou melhor do que você naquele dia.', a: 'Roger Federer', p: 'Lenda do tênis' },
  { t: 'Vitórias morais não contam.', a: 'Savielly Tartakower', p: 'Grande mestre de xadrez' },
  { t: 'Nunca confunda atividade com realização.', a: 'John Wooden', p: 'Técnico lendário de basquete' },
  { t: 'Quem ataca às vezes se arrepende de lances ruins, mas é muito pior se arrepender para sempre de uma oportunidade que você deixou passar.', a: 'Garry Kasparov', p: 'Campeão mundial de xadrez' },
  { t: 'Eu nunca disse a maioria das coisas que eu disse.', a: 'Yogi Berra', p: 'Lenda do beisebol' },
];
